library(poweRlaw)

fmax <- 0.2 # 0.3333 0.2 0.1
pPos <- 0.5 # 0.5
folderName <- "./degree_sequences_np/"

fig_foldername <- "/Users/fionacallahan/Documents/Nielsen_lab/TheoryCoOccur/figures/"
cutoffalpha <- 0.01
nSpec <- 100
if (nSpec == 100) {
  y_ticks <- c(0.01, 0.1, 1)  # consistent y-axis ticks for all plots
} else {
  y_ticks <- c(0.001, 0.01, 0.1, 1)  # consistent y-axis ticks for all plots
}

# Function to create a single plot
create_fit_plot <- function(dist_type, network_type) {
  # Load the saved model data
  load(paste0(folderName, "models_", dist_type, nSpec, "_fmax", fmax, "_pPos", pPos, "_", network_type, ".RData"))

  if (network_type == "cooc") {
    # plot cCDF of data
    plot(pois_cooc,
        ylab = "cCDF (log scale)",
        xlab = "Node degree (log scale)",
        ylim = c(min(y_ticks), 1),
        yaxt = "n",
        cex.lab = 1.2)
    axis(2, at = y_ticks, labels = y_ticks, las = 1)
    # plot fits
    lines(powLaw_cooc, col = "blue", lwd = 2)
    lines(pois_cooc, col = "red", lwd = 2)
    lines(logn_cooc, col = "black", lwd = 2)
    lines(exp_cooc, col = "orange", lwd = 2)
  } else {
    # plot cCDF of data
    plot(pois_inter,
        ylab = "cCDF (log scale)",
        xlab = "Node degree (log scale)",
        ylim = c(min(y_ticks), 1),
        yaxt = "n",
        cex.lab = 1.2)
    axis(2, at = y_ticks, labels = y_ticks, las = 1)
    lines(powLaw_inter, col = "blue", lwd = 2)
    lines(pois_inter, col = "red", lwd = 2)
    lines(logn_inter, col = "black", lwd = 2)
    lines(exp_inter, col = "orange", lwd = 2)
  }

  legend("bottomleft",
         legend = c("Power law", "Poisson", "Log-normal", "Exponential"),
         col = c("blue", "red", "black", "orange"),
         lty = 1, lwd = 2, cex = 1.2)
}

# Create high-quality grid plot
png(filename = paste0(fig_foldername, "plotFits_grid_nspec", nSpec, "_cutoffalpha", cutoffalpha, "_fmax", fmax, "_pPos", pPos, ".png"),
    width = 5000, height = 4000, res = 600)

# Set up layout with margins for labels
# Outer margins: bottom, left, top, right
par(mfrow = c(2, 2),
    mar = c(4, 4, 2, 1),    # Individual plot margins
    oma = c(1, 6, 4, 1))    # Outer margins for labels

# Row 1: Power law
create_fit_plot("power", "inter")
create_fit_plot("power", "cooc")

# Row 2: Random (Binomial)
create_fit_plot("rand", "inter")
create_fit_plot("rand", "cooc")

# Add column labels at top
mtext("Interaction", side = 3, line = 0, outer = TRUE, at = 0.25, cex = 1.2, font = 2)
mtext("Co-occurrence", side = 3, line = 0, outer = TRUE, at = 0.75, cex = 1.2, font = 2)

# Add row labels on left side
mtext("Power law", side = 2, line = 2, outer = TRUE, at = 0.75, cex = 1.2, font = 2, las = 0)
mtext("Random (binomial)", side = 2, line = 2, outer = TRUE, at = 0.25, cex = 1.2, font = 2, las = 0)

dev.off()

cat("Grid plot saved to:", paste0(fig_foldername, "plotFits_grid_nspec", nSpec, "_cutoffalpha", cutoffalpha, "_fmax", fmax, "_pPos", pPos, ".png\n"))



